/**
 * CyBlockBees 关卡序列（离线生成，运行时只读）。
 *
 * 数据取自 X-Clash（com.xman.sea.gp）里 CyBlockBees 小游戏原作的关卡 prefab：
 * 游玩顺序与画线额度来自 `levelconfigcsv.csv`（Index / trueIndex / dtDrawMax），
 * 元素布局来自 `level{trueIndex}.prefab`。共 208 关、3802 个元素、
 * 多边形碰撞点 71079 个。
 *
 * 保留启用的物理/Lua 入口、运行时生成的地形、刚体、关节、渲染尺寸和对象引用；
 * 位置与缩放是相对关卡根的世界值（关卡根恒为原点、单位缩放），`rot` 是绕 Z 的弧度。
 *
 * 紧凑格式 v2：定长小端二进制后 Base64。整数都是定点——
 * 位置 ×100、缩放 ×1000、旋转 ×1000、多边形点 ×100、参数 ×10000。
 * prefab detail 表完整保存复合碰撞体、运行时地形、刚体、关节和视觉；基础索引用二进制编码。
 * 解码是纯 JS，浏览器与微信小游戏都不依赖 atob / Buffer / wx。
 *
 * 重新生成：
 *   python3 project-scripts/cyblockbees/build-level-bank.py --xapk <X-Clash.xapk>
 * 数据来源：/Users/laitao/Downloads/x-clash-1-0-118.xapk
 */

import type { CyBlockBeesPrefab } from './CyBlockBeesPrefab';

/** 元素语义名，下标即二进制里的 kind id。 */
export const CYBLOCKBEES_KINDS = [
    'dog',
    'hive',
    'water',
    'cloud',
    'drawGround',
    'drawRedArea',
    'drawBox',
    'drawBoxMid',
    'drawBoxLong',
    'box',
    'ice',
    'spike',
    'saw',
    'brick',
    'balloon',
    'balloonDog',
    'balloonBomb',
    'balloonSaw',
    'balloonHive',
    'balloonRope',
    'bomb',
    'knife',
    'wind',
    'spider',
    'stone',
    'jelly',
    'moveable',
    'blackHole',
    'ciqiu',
    'ciqiuJoint',
    'round',
    'platform',
    'moveableBrick',
    'grass',
    'tree',
    'beeSpawn',
    'hand',
    'levelRoot',
    'bone',
    'support',
] as const;

export type CyBlockBeesElementKind = (typeof CYBLOCKBEES_KINDS)[number];

/** 元素可序列化参数键，下标即二进制里的 key id。 */
export const CYBLOCKBEES_PARAM_KEYS = [
    'cornerPercent',
    'curveSegments',
    'dtCount',
    'dtInitCount',
    'dtInterval',
    'dtIsLeft',
    'dtIsPlatform',
    'dtIsSingle',
    'dtRopePartCount',
    'dtRopePartLength',
    'dtSpeed',
    'lineOffset',
    'lineOffset2',
    'lineSegment',
    'lineWidth',
    'lineWidth2',
    'needGenOutlinePhy',
    'outLineAngleRange',
    'outLineSidePercent',
    'outlineWidth',
    'dtCanMove',
    'moveSpeed',
    'moveDistance',
] as const;

export type CyBlockBeesParamKey = (typeof CYBLOCKBEES_PARAM_KEYS)[number];

export interface CyBlockBeesBoxCollider {
    readonly shape: 'box';
    readonly width: number;
    readonly height: number;
    readonly offsetX: number;
    readonly offsetY: number;
}

export interface CyBlockBeesCircleCollider {
    readonly shape: 'circle';
    readonly radius: number;
    readonly offsetX: number;
    readonly offsetY: number;
}

export interface CyBlockBeesPolygonCollider {
    readonly shape: 'polygon';
    /** 每条路径是一串 [x, y]，单位与元素缩放一致。 */
    readonly paths: readonly (readonly number[])[];
}

export type CyBlockBeesCollider =
    | CyBlockBeesBoxCollider
    | CyBlockBeesCircleCollider
    | CyBlockBeesPolygonCollider;

export interface CyBlockBeesElement {
    readonly detail: CyBlockBeesPrefab;
    readonly kind: CyBlockBeesElementKind;
    readonly x: number;
    readonly y: number;
    readonly scaleX: number;
    readonly scaleY: number;
    /** 绕 Z 的旋转（弧度）。 */
    readonly rotation: number;
    readonly collider: CyBlockBeesCollider | null;
    /** 来自原作 `luaData.SerializedValues` 的参数；没有则为空对象。 */
    readonly params: Readonly<Partial<Record<CyBlockBeesParamKey, number>>>;
}

export interface CyBlockBeesLevel {
    /** 游玩顺序，从 1 开始。 */
    readonly level: number;
    /** 原作 prefab 编号（仅用于问题追踪）。 */
    readonly sourcePrefab: number;
    /** 原作的 dtDrawMax：本关允许画出的总长度。 */
    readonly drawBudget: number;
    readonly elements: readonly CyBlockBeesElement[];
}

