const BASE64_ALPHABET =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** 纯 JS Base64 解码：不依赖 atob / Buffer，微信小游戏可直接用。 */
function decodeBase64(encoded: string): Uint8Array {
    if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(encoded)) {
        throw new Error('Invalid CyBlockBees level bank Base64.');
    }
    const padding = encoded.endsWith('==') ? 2 : encoded.endsWith('=') ? 1 : 0;
    const bytes = new Uint8Array((encoded.length / 4) * 3 - padding);
    let bits = 0;
    let value = 0;
    let output = 0;
    for (let i = 0; i < encoded.length - padding; i += 1) {
        value = (value << 6) | BASE64_ALPHABET.indexOf(encoded[i]);
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            bytes[output] = (value >>> bits) & 255;
            output += 1;
            value &= (1 << bits) - 1;
        }
    }
    return bytes;
}

function decodeCyBlockBeesLevels(encoded: string): readonly CyBlockBeesLevel[] {
    const bytes = decodeBase64(encoded);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    let cursor = 0;
    const u8 = (): number => bytes[cursor++];
    const i16 = (): number => { const v = view.getInt16(cursor, true); cursor += 2; return v; };
    const u16 = (): number => { const v = view.getUint16(cursor, true); cursor += 2; return v; };
    const i32 = (): number => { const v = view.getInt32(cursor, true); cursor += 4; return v; };

    const version = u8();
    if (version !== 2) {
        throw new Error(`Unsupported CyBlockBees level bank version ${version}.`);
    }
    const levelCount = u8();
    const shapeCount = u16();
    const shapes: CyBlockBeesPolygonCollider[] = [];
    for (let s = 0; s < shapeCount; s += 1) {
        const pathCount = u8();
        const paths: number[][] = [];
        for (let p = 0; p < pathCount; p += 1) {
            const pointCount = u8();
            const path: number[] = [];
            for (let q = 0; q < pointCount; q += 1) {
                path.push(i16() / 100, i16() / 100);
            }
            paths.push(path);
        }
        shapes.push({ shape: 'polygon', paths });
    }
    const levels: CyBlockBeesLevel[] = [];
    for (let i = 0; i < levelCount; i += 1) {
        const level = u8();
        const sourcePrefab = u16();
        const drawBudget = u8();
        const elementCount = u16();
        const elements: CyBlockBeesElement[] = [];
        for (let e = 0; e < elementCount; e += 1) {
            const kind = CYBLOCKBEES_KINDS[u8()];
            const x = i16() / 100;
            const y = i16() / 100;
            const scaleX = i16() / 1000;
            const scaleY = i16() / 1000;
            const rotation = i16() / 1000;
            let collider: CyBlockBeesCollider | null = null;
            const shape = u8();
            if (shape === 1) {
                collider = {
                    shape: 'box',
                    width: i16() / 100,
                    height: i16() / 100,
                    offsetX: i16() / 100,
                    offsetY: i16() / 100,
                };
            } else if (shape === 2) {
                collider = {
                    shape: 'circle',
                    radius: i16() / 100,
                    offsetX: i16() / 100,
                    offsetY: i16() / 100,
                };
            } else if (shape === 3) {
                collider = shapes[u8()];
            }
            const paramCount = u8();
            const params: Partial<Record<CyBlockBeesParamKey, number>> = {};
            for (let p = 0; p < paramCount; p += 1) {
                const key = CYBLOCKBEES_PARAM_KEYS[u8()];
                const value = i32() / 10000;
                params[key] = value;
            }
            elements.push({ kind, x, y, scaleX, scaleY, rotation, collider, params, detail: PREFAB_DETAILS[i][e] });
        }
        levels.push({ level, sourcePrefab, drawBudget, elements });
    }
    return levels;
}

/** 全部关卡，按游玩顺序排列。 */
export const CYBLOCKBEES_LEVELS: readonly CyBlockBeesLevel[] =
    decodeCyBlockBeesLevels(CYBLOCKBEES_BANK_BASE64);

export function getCyBlockBeesLevel(level: number): CyBlockBeesLevel | undefined {
    return CYBLOCKBEES_LEVELS[level - 1];
}
